// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
// REFUSES to provision unless the account has a way to bill the renewal (a saved
// card OR a wallet balance that already covers one renewal), it is idempotent
// against double-submit, and it then delegates the ACTUAL charge to the audited
// `orderHostingAccount` above — one debit path, never a second one.
//
// displayed === charged === renewed: this action computes NO price of its own for
// the debit. The wallet debit + the first-month-free reserve→confirm→release
// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).

export type HostingOrderInput = {
  planId: string;
  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
  domain?: string;
  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
  subdomainLabel?: string;
  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
  extraDiskGB?: number;
  termMonths?: number;
  /** Optional catalog app to auto-install after the account provisions. */
  appSlug?: string;
  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
  idempotencyKey: string;
  /**
   * "Apply my balance" — mirrors the VPS wizard toggle. Defaults ON (only an explicit
   * `false` turns it off) so every existing caller keeps applying the wallet first.
   * When the balance doesn't fully cover the amount due today — because the toggle is
   * off, or the balance is short — the remainder is charged to a card (funding the
   * wallet), exactly like VPS.
   */
  useWallet?: boolean;
};

export type HostingOrderResult =
  | { ok: true; accountId: string }
  | { error: string }
  /** No renewal-capable payment method yet — the wizard must capture a card first. */
  | { needCard: true; renewalCents: number }
  /** A card leg is due: mount this embedded Stripe checkout; fulfilment places the order. */
  | { checkout: EmbeddedCheckout };

/**
 * The full-price single renewal of a plan/term — the gate threshold, identical to
 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
 */
async function hostingRenewalCents(plan: { priceCents: number }, term: number, extraGB = 0): Promise<number> {
  const annualPct = await annualDiscountPct();
  const perGbCents = await extraDiskPerGbCents();
  return termPriceCents(plan.priceCents, term, annualPct) + extraDiskCentsAt(extraGB, perGbCents) * term;
}

/** Place a hosting order from the checkout wizard. See the block comment above. */
export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
  const user = await requireUser();
  // Caught so an impersonating admin sees this message inline instead of a page
  // crash — the bare throw used to hit the wizard's generic error screen on
  // every payment attempt.
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy?product=hosting, captured into a cookie by
  // PartnerSourceCapture). Threaded into BOTH the wallet leg (below) and the card
  // leg (via the Stripe-metadata-round-tripped intent).
  const partnerSource = partnerSourceFromCookie(await cookies());

  const key = String(input.idempotencyKey ?? "").trim();
  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };

  const term = normalizeProductTerm(input.termMonths);
  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };

  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
  const renewalCents = await hostingRenewalCents(plan, term, extraGB);

  // WALLET/CARD SPLIT — the money-path fork mirroring VPS `payAndDeploy`. The amount
  // due TODAY (after any first-month-free credit) is split against the balance and the
  // "apply my balance" toggle; `useWallet` defaults ON so the existing behaviour is
  // unchanged. This computes the SAME anticipated dueToday `orderHostingAccountFor`
  // charges (shared `hostingChargeCents`), so the card leg is a real part of the same
  // total, never a second price.
  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
  // Partner discount included (hostingOrderDueCents) — the same figure the
  // wizard quoted and orderHostingAccountFor debits.
  const { dueCents: dueTodayCents } = await hostingOrderDueCents(plan, term, extraGB, {
    userId: user.id,
    firstMonthFreeEligible: eligible,
  });
  const useWallet = input.useWallet !== false;
  const { cardCents } = walletSplit({ dueCents: dueTodayCents, balanceCents: user.balanceCents, useWallet });

  if (cardCents > 0) {
    // A card leg is due (the toggle is off, or the balance is short). Fund it by card
    // — the card is saved via `setup_future_usage`, which is ALSO the renewal method
    // the gate below requires, so there is no `needCard` on this path. On payment,
    // `fulfilCheckoutSession` credits the card amount to the wallet and calls
    // `placeHostingOrderCore` with these SAME inputs (and the same `hostorder:<key>`
    // idempotency), which debits the real charge — one debit path, unchanged.
    const checkout = await createHostingOrderPaymentSession(user, cardCents, {
      planId: input.planId,
      domain: input.domain,
      subdomainLabel: input.subdomainLabel,
      extraDiskGB: extraGB || undefined,
      termMonths: term,
      appSlug: input.appSlug,
      idempotencyKey: key,
      partnerSource,
    });
    if (!checkout) return { error: "Card payments aren’t set up yet — top up your wallet to deploy." };
    return { checkout };
  }

  // cardCents <= 0 → the wallet covers the amount due today (or it is $0). EXISTING
  // wallet path, byte-for-byte — including the RENEWAL-METHOD GATE: never provision a
  // paid product with no way to bill the renewal. A saved card OR a wallet already
  // holding one renewal's worth qualifies; otherwise the wizard captures a card.
  //
  // EXCEPT the genuine first-month-free case (`eligible && dueTodayCents === 0` —
  // a single-month term, no disk add-on, nothing left to pre-authorize today): the
  // owner's explicit call is that a free first month must not demand a card up
  // front. That does trade away the renewal guarantee for these orders — if no
  // card is ever added, month two's renewal sweep (worker/product-renewals.ts)
  // fails to charge it, same as any other customer whose card later expires or
  // declines, and the account lands in the SAME outstanding-balance/suspended
  // state that path already handles (BillingView's OutstandingBalanceBanner +
  // SettleBalanceModal) rather than a new failure mode.
  const freeFirstMonth = eligible && dueTodayCents === 0;
  if (!freeFirstMonth && !hasChargeableCard(user) && user.balanceCents < renewalCents) {
    return { needCard: true, renewalCents };
  }
  return placeHostingOrderCore(user, input, key, term, plan, extraGB, renewalCents, partnerSource);
}

/**
 * The idempotent placement + post-order bookkeeping, WITHOUT the auth/pricing/split
 * preamble — takes the loaded `user` explicitly so BOTH the interactive action
 * (`placeHostingOrder`, wallet path) and the card-funded fulfilment path
 * (`fulfilCheckoutSession`) drive the SAME `hostorder:<key>` idempotency claim and the
 * SAME audited `orderHostingAccountFor` debit. On the card path the wallet was already
 * topped up by `creditCheckoutSession` before this runs.
 */
async function placeHostingOrderCore(
  user: User,
  input: HostingOrderInput,
  key: string,
  term: number,
  plan: { maxDatabases: number },
  extraGB: number,
  renewalCents: number,
  partnerSource?: string,
): Promise<HostingOrderResult> {
  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
  // token table. A rapid resubmit or a network retry with the same key can't create
  // a second account or take a second debit.
  const sessionKey = `hostorder:${key}`;
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
  } catch (e) {
    if (isUniqueViolation(e)) {
      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
      // A completed prior attempt: replay its result (no second charge).
      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
      // A failed prior attempt: clear it so an explicit retry can proceed.
      if (prior?.status === "FAILED") {
        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
      } else {
        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
        return { error: "That order is already being placed — check your hosting accounts in a moment." };
      }
      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
      try {
        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
      } catch {
        return { error: "That order is already being placed — check your hosting accounts in a moment." };
      }
    } else {
      throw e;
    }
  }

  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
  // the free temporary subdomain. All money movement, the first-month-free atomic
  // claim and the hostname claim happen inside orderHostingAccountFor's transaction.
  const res = await orderHostingAccountFor(user, input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB, partnerSource);
  /* Only two outcomes are legitimate HERE. This runs AFTER the card cleared, so
     a `checkout` (another card leg) or `needCard` would mean the customer has
     paid and no account was opened — an anomaly worth recording as FAILED under
     its own wording rather than letting an unhandled branch fall through as
     success. `HostingOrderResult` is a union, so each branch has to be read
     explicitly; the old `HostingResult` had every field optional, which is what
     let `{ checkout }` pass silently as "no error, no accountId". */
  const failed = async (why: string) => {
    await db.fulfilledSession
      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: why.slice(0, 500) } })
      .catch(() => {});
    return { error: why };
  };
  /* Narrowed one branch at a time so `res` itself is refined — after these
     three, it is the `{ ok: true; accountId: string }` member and `accountId`
     is known present. */
  if ("error" in res) return failed(res.error);
  if ("checkout" in res) return failed("The order still wanted a card payment after one had already cleared.");
  if ("needCard" in res) return failed("The order asked for a card to be added after one had already cleared.");
  if (!res.accountId) return failed("order failed");
  await db.fulfilledSession
    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
    .catch(() => {});

  // Deploy-funnel COMPLETION — hosting's authoritative, server-side bottom of the
  // funnel, the counterpart to placeOrder / placeGameOrder. Hosting does NOT flow
  // through the shared Stripe fulfilment bus (lib/fulfil-checkout.ts has no hosting
  // kind — a $0 first month captures a card in `mode:"setup"`, and the charge is the
  // wallet debit inside orderHostingAccount), so THIS is its shared success path.
  // Recorded here (not on the idempotent-replay early return above) so a retry never
  // double-counts. Replaces the client-side trackDeployComplete removed from
  // HostingDeployWizard, keeping all three products on one authoritative userId-keyed
  // completion. Best-effort + double-guarded so it can never disturb the placed order.
  try {
    await recordDeployFunnelComplete({ product: "hosting", step: "Complete", stepIndex: 7, userId: user.id });
  } catch {
    /* never let funnel bookkeeping affect a completed order */
  }

  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
  // side), so an ad blocker / privacy browser silently drops it and the campaign
  // never learns the signup happened. Firing it here too — with the SAME event_id
  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
  // conversion when the pixel DOES load, and still counts it when the pixel is
  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.

"use server";

import { placeHostingOrder } from "@/lib/actions-hosting";
import { orderEmailHosting } from "@/lib/actions-email-hosting";

/* Form adapters for the two products whose order functions are not FormData-shaped.
 *
 * `payAndDeploy`, `payAndDeployGame` and `purchaseDomain` all take
 * `(prev, formData)`, so the wizard posts hidden fields straight to them.
 * `orderHostingAccount` and `orderEmailHosting` take POSITIONAL arguments, so
 * they need something between the form and the function.
 *
 * THE RULE FOR EVERYTHING IN THIS FILE: it translates, it does not decide.
 * No pricing, no eligibility, no wallet arithmetic, no validation beyond
 * reading strings out of a FormData. Every one of those already lives inside
 * the real function — impersonation refusal, the email-verification gate, the
 * domain-uniqueness check, the wallet/card split — and a second copy here would
 * be a second set of rules guarding the same money, free to drift.
 *
 * Both exports are network-callable (`"use server"` makes every export so), and
 * both are spend paths. That is acceptable ONLY because each is a thin call into
 * a function that does its own authorisation. Do not add anything here that
 * authorises, prices, or charges on its own.
 */

export type SubmitState = { error?: string; ok?: boolean; checkout?: { clientSecret: string; publishableKey: string } };

/** Place a shared-hosting order from the wizard's form. */
export async function submitHosting(_prev: SubmitState, formData: FormData): Promise<SubmitState> {
  /* `placeHostingOrder`, NOT `orderHostingAccount`.
   *
   * They are not variants of one another. `orderHostingAccount` takes no
   * `useWallet` argument at all, so it ALWAYS spends the balance when the
   * balance covers the cost — which means it always places the order and never
   * yields a Stripe session. The wizard's "use account balance" toggle had
   * nowhere to send its value, the card fields could therefore never appear for
   * hosting, and calling it to obtain a session instead created a real account
   * every time (200 of them, in this sandbox, before it hit the node's cap).
   *
   * `placeHostingOrder` is the wallet-aware entry point: it honours the toggle,
   * returns `{ checkout }` when a card leg is due WITHOUT placing anything, and
   * only commits when the balance actually covers the total. Everything else —
   * pricing, the promo claim, the hostname claim, the impersonation and
   * email-verification gates — stays inside it. */
  const res = await placeHostingOrder({
    planId: String(formData.get("planId") ?? ""),
    domain: String(formData.get("domain") ?? "").trim() || undefined,
    subdomainLabel: String(formData.get("subdomainLabel") ?? "").trim() || undefined,
    termMonths: Number(formData.get("termMonths") ?? 1),
    extraDiskGB: Number(formData.get("extraDiskGB") ?? 0) || undefined,
    idempotencyKey: String(formData.get("idempotencyKey") ?? ""),
    /* Only an explicit "0" declines the balance, matching the action's own
       default rather than re-deciding it here. */
    useWallet: formData.get("useWallet") !== "0",
  });

  if ("error" in res) return { error: res.error };
  if ("needCard" in res) {
    return { error: "Add a payment card to your account first — this plan renews automatically." };
  }
  if ("checkout" in res) return { checkout: res.checkout };
  return { ok: true };
}

/** Place a business-email order from the wizard's form. */
export async function submitEmail(_prev: SubmitState, formData: FormData): Promise<SubmitState> {
  const domainName = String(formData.get("domain") ?? "").trim();
  const emailPlanId = String(formData.get("planId") ?? "");
  const termMonths = Number(formData.get("termMonths") ?? 1);
  // Defaults ON, and only an explicit "0" turns it off — matching the real
  // function's own default rather than re-deciding it here.
  const useWallet = formData.get("useWallet") !== "0";

  const res = await orderEmailHosting(domainName, emailPlanId, termMonths, useWallet);
  /* Error first: a result carrying BOTH would otherwise be reported as a
     checkout to mount rather than a problem to show. */
  if ("error" in res && res.error) return { error: res.error };
  if ("checkout" in res && res.checkout) return { checkout: res.checkout };
  return { ok: true };
}
  const subLabelTrim = subLabel.trim().toLowerCase();
  useEffect(() => {
    if (domainMode !== "temp") {
      setSubCheck({ status: "idle" });
      return;
    }
    const label = subLabel.trim().toLowerCase();
    if (!label) {
      setSubCheck({ status: "idle" });
      return;
    }
    setSubCheck({ status: "checking" });
    let cancelled = false;
    const t = setTimeout(async () => {
      try {
        const r = await checkHostingSubdomain(label);
        if (!cancelled) setSubCheck(r.available ? { status: "ok" } : { status: "bad", reason: r.reason });
      } catch {
        if (!cancelled) setSubCheck({ status: "bad", reason: "Couldn’t check right now — try again." });
      }
    }, 400);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [subLabel, domainMode]);

  const subdomainBlocker =
    domainMode === "temp" && subLabelTrim.length > 0 && subCheck.status !== "ok"
      ? subCheck.status === "checking"
        ? "Checking availability…"
        : subCheck.reason ?? "Pick an available subdomain."
      : null;

  const canContinue = curLabel === "Domain" ? !domainBlocker && !subdomainBlocker : true;
  const canPlace = !!planId && !busy && !domainBlocker && !subdomainBlocker;

  async function place() {
    if (!plan) return;
    setBusy(true);
    setError("");
    setStripePhase("loading");
    // Deploy-funnel: the customer submitted the final Review, so an order (a wallet
    // charge, or the renewal-method gate) is about to be attempted — record REACHED-
    // PAYMENT as a step at the tail (after Review). De-duped per session; completion
    // is now recorded server-side in placeHostingOrder (userId-keyed), so this wizard
    // no longer fires trackDeployComplete.
    trackDeployStep("hosting", "Payment", steps.length);
    try {
      const res = await placeHostingOrder({
        planId,
        domain: domainMode === "own" ? domainTrim : undefined,
        subdomainLabel: domainMode === "temp" && subLabelTrim ? subLabelTrim : undefined,
        extraDiskGB: extraDiskGB || undefined,
        termMonths,
        appSlug: appSlug || undefined,
        idempotencyKey: idemRef.current,
        useWallet,
      });
      // A card leg is due — mount the embedded Stripe checkout. On success Stripe
      // navigates the top window to the confirm route, which credits the card to the
      // wallet, places the account (debiting it) and lands the customer on it.
      if ("checkout" in res) {
        setCheckoutSession({ clientSecret: res.checkout.clientSecret, publishableKey: res.checkout.publishableKey });
        setStripePhase("idle");
        return;
      }
      if ("needCard" in res) {
        setCardNote("Add a renewal payment method to continue — a $0 first month still needs a way to bill month two.");
        setStep(steps.length - 1);
        return;
      }
      if ("error" in res) {
        setError(res.error || "Something went wrong. Your wallet was not charged — try again.");
        setStripePhase("error");
        trackDeployError("hosting", "Review", steps.length - 1, "ORDER_ERROR", res.error);
        return;
      }
      // Success — the deploy went through. Completion is recorded AUTHORITATIVELY on
      // the server (placeHostingOrder → recordDeployFunnelComplete), keyed by userId
      // like VPS and game, so it is counted once even if this browser never gets here
      // (and is not double-counted against the server event). No client complete beacon.
      try {
        sessionStorage.removeItem(DRAFT_KEY);
      } catch {
        /* ignore */
      }
      // Fire the "hosting" conversion for a completed hosting signup (→ Meta
      // Subscribe + the Google Ads hosting label). The first-month-free ad funnel
      // optimizes toward THIS event, not Purchase: the order is $0 today (free
      // month) and the real revenue is the renewal, so Purchase would be a $0/late
      // signal. `nxTrack` is the consent-gated global from ConversionTags — a no-op
      // until the visitor consents + the pixel loads.
      try {
        (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.(
          "hosting",
          // Value = the recurring term charge (what they renew at — first month is
          // free, so this is the real subscription value for ROAS, not $0-today).
          { value: renewalCents / 100, currency: "USD", eventId: idemRef.current },
        );
      } catch {
        /* ignore */
      }
      // `?purchase=1` — same marker reportPurchase stamps onto the card-paid path
      // (lib/fulfil-checkout.ts) and the VPS/game wallet-only redirects (lib/actions.ts)
      // — so <ProvisioningOverlay/> knows this landing IS a fresh order, even in
      // SANDBOX mode where the account can already be ACTIVE by the time this page
      // loads. Without it, a wallet-only hosting order showed no post-payment
