// Server actions behind the "card on file" section of the customer billing page.
//
// The whole flow is redirect-based (Stripe hosted Checkout in `mode: "setup"`),
// because no Stripe Elements / Stripe.js integration exists in this codebase and
// no publishable key is plumbed to the browser. That means there is a moment where
// the card exists at Stripe and not here, which is exactly the shape of the
// fulfilment bug that cost a customer their server once already — see
// `adoptUnclaimedCards` in `lib/stripe-cards.ts` for the backstop.
//
// ROUTE NOTE: `app/api/stripe/**` is owned elsewhere, so the return leg is NOT an
// API route. Stripe redirects to `/dashboard/billing?card_setup=<session_id>` and
// a small client component calls `finalizeCardSetup` below. If a route is wanted
// later, the natural one is `GET /api/stripe/setup-return?session_id=…` calling
// `saveCardFromSetupSession(sessionId, currentUser().id)` and redirecting to
// `/dashboard/billing?card=saved`.

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { stripeConfigured, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";
import { annualDiscountPct } from "./annual-discount";
import { extraDiskPerGbCents } from "./disk-expand";
import { backupPlusMonthlyCents } from "./backup-upgrade";
import { taxContextForUser } from "./tax";
import {
  CARD_REMOVED,
  CARD_SETUP_STARTED,
  cardDisplayLabel,
  createCardSetupSession,
  createOutstandingEmbedded,
  detachSavedCard,
  renewalCharge,
  retryDunningNow,
  saveCardFromSetupSession,
} from "./stripe-cards";

/**
 * Begin saving a card. Returns the hosted Checkout URL for the browser to follow.
 *
 * The `card.setup_started` audit row is not just bookkeeping: it is the evidence
 * `adoptUnclaimedCards` requires before it will adopt a card that is attached at
 * Stripe but was never confirmed here, which is what keeps a REMOVED card from
 * being silently resurrected.
 */
export async function startCardSetup(): Promise<{ clientSecret?: string; publishableKey?: string; error?: string }> {
  // An admin impersonating a customer must not be able to put a card on their
  // account — the same reasoning that blocks impersonated wallet spend.
  await assertNotImpersonating();
  const user = await requireUser();
  if (!stripeConfigured()) {
    return { error: "Card payments aren't configured on this installation yet." };
  }
  try {
    const res = await createCardSetupSession(user);
    if (!res) return { error: "Stripe didn't return a setup session. Please try again." };
    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
    return { clientSecret: res.clientSecret, publishableKey: res.publishableKey };
  } catch (e) {
    console.error("[payment-method] setup session failed", e);
    return { error: "We couldn't start card setup just now. Please try again in a moment." };
  }
}

/**
 * Finish saving a card after Stripe redirects back.
 *
 * Safe to call repeatedly with the same session id — it re-reads the same payment
 * method from Stripe and writes the same columns, so a refreshed tab is a no-op
 * rather than a second card.
 */
export async function finalizeCardSetup(
  sessionId: string,
): Promise<{ ok?: boolean; label?: string; error?: string }> {
  await assertNotImpersonating();
  const user = await requireUser();
  if (!sessionId) return { error: "Missing card setup reference." };

  const res = await saveCardFromSetupSession(sessionId, user.id);
  if (res.error || !res.card) return { error: res.error ?? "The card wasn't saved." };

  const label = cardDisplayLabel(res.card) ?? "Card saved";
  await db.auditLog.create({ data: { userId: user.id, action: "card.saved", detail: label } });
  // Anyone mid-dunning was told we'd charge a new card straight away; make it true.
  const requeued = await retryDunningNow(user.id);
  if (requeued > 0) {
    await db.notification.create({
      data: {
        userId: user.id,
        title: "Card saved — we'll retry your renewal shortly",
        body: `We'll charge ${label} for the outstanding renewal within the next few minutes. Nothing is suspended.`,
        href: "/dashboard/billing",
      },
    });
  }
  revalidatePath("/dashboard/billing");
  return { ok: true, label };
}

/** Remove the card on file (detaches at Stripe first — see `detachSavedCard`). */
export async function removeSavedCard(): Promise<{ ok?: boolean; error?: string }> {
  await assertNotImpersonating();
  const user = await requireUser();
  const label = cardDisplayLabel({
    brand: user.cardBrand,
    last4: user.cardLast4,
    expMonth: user.cardExpMonth,
    expYear: user.cardExpYear,
  });
  const res = await detachSavedCard(user.id);
  if (res.error) return { error: res.error };
  await db.auditLog.create({
    data: { userId: user.id, action: CARD_REMOVED, detail: label ?? "card on file" },
  });
  revalidatePath("/dashboard/billing");
  return { ok: true };
}

/**
 * Mint a FRESH hosted-Checkout link for a server's outstanding renewal balance.
 *
 * A link is minted on demand rather than reusing the stored `dunningPayUrl`
 * because Stripe Checkout sessions expire within 24 hours while the dunning
 * sequence runs for six days — surfacing the stored link in the portal would show
 * an expired Stripe page to a customer trying to pay us.
 */
export async function settleOutstanding(
  serverId: string,
): Promise<{ checkout?: EmbeddedCheckout; error?: string; covered?: boolean; amountCents?: number }> {
  const user = await requireUser();
  if (!stripeConfigured()) {
    return { error: "Card payments aren't configured — add funds to your wallet instead." };
  }
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, gamePlan: true, dedicatedIp: true, user: true },
  });
  if (!server) return { error: "Server not found." };
  if (server.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden" };
  if (server.isFree || !server.expiresAt) return { error: "This server has nothing outstanding." };

  // EVERY figure below is the OWNER's, never the caller's.
  //
  // The admin branch above lets staff mint this link on a customer's behalf, and
  // until now the split was computed from `user.balanceCents` and the session was
  // stamped with `user.id` — the ADMIN's wallet and the ADMIN's account. So an
  // admin settling a customer's balance quoted a remainder against their own
  // credit and produced a Checkout session whose payment credits the admin's
  // wallet, leaving the customer's server exactly as unpaid as before. Worse, the
  // link is stored on `Server.dunningPayUrl` and `worker/billing.ts` reuses a
  // stored link verbatim in the "your bank needs to confirm" email — so the
  // CUSTOMER would be emailed a page that pays money into someone else's wallet.
  // The balance belongs to the server's owner, so the whole quote does.
  const owner = server.user;
  const charge = renewalCharge(server, {
    ipMonthlyCents: await dedicatedIpMonthlyCents(),
    extraDiskPerGbCents: await extraDiskPerGbCents(),
    backupPlusCents: await backupPlusMonthlyCents(),
    annualDiscountPct: await annualDiscountPct(),
    // VAT/GST for the owner's country (Finding 1) so this quoted card leg matches the
    // tax-inclusive total the sweep will debit — quote here === charge there.
    taxRatePercent: (await taxContextForUser(owner)).ratePercent,
  });
  // Wallet credit first, card for the remainder — the same split the sweep will
  // apply, so the quote here and the charge there can never disagree.
  const split = walletSplit({
    dueCents: charge.totalCents,
    balanceCents: owner.balanceCents,
    useWallet: true,
  });
  if (split.cardCents === 0) {
    return {
      covered: true,
      error:
        server.userId === user.id
          ? "Your wallet already covers this renewal — it completes automatically within a few minutes."
          : "This customer's wallet already covers the renewal — it completes automatically within a few minutes.",
    };
  }

  const checkout = await createOutstandingEmbedded({
    user: owner,
    amountCents: split.cardCents,
    hostname: server.hostname,
    serverId: server.id,
  });
  if (!checkout) return { error: "We couldn't start checkout just now. Please try again in a moment." };
  // Deliberately DON'T write `dunningPayUrl`: an embedded session has no URL, and
  // that column is the worker's "dunning email already sent" sentinel + the hosted
  // link it mints for the inbox. The worker keeps its own hosted link current; this
  // in-portal modal is a parallel way to pay the same balance (both credit the
  // wallet, the sweep applies it — paying twice just banks surplus credit).
  //
  // `amountCents` is returned purely for display (the card leg the caller is
  // about to be charged) — the Checkout Session above is what actually charges
  // it, so a UI that mislabels this number cannot desync from what Stripe bills.
  return { checkout, amountCents: split.cardCents };
}
// Saved-card / off-session charging primitives for subscription renewals.
//
// WHY THIS FILE EXISTS
// Until now a renewal could only debit the wallet (`worker/billing.ts` ->
// `debitWallet`). A customer with a perfectly good card on file was suspended the
// moment their wallet emptied, because `User.stripePaymentMethodId` was never
// written and never read. Everything needed to charge a card lives here; the
// worker owns the *policy* (when to retry, when to suspend), this module owns the
// *mechanics* (attach a card, charge it, credit the wallet for what it paid).
//
// THE MONEY MODEL — identical to checkout, deliberately
// Checkout applies wallet credit first and puts only the remainder on the card
// (`lib/wallet-split.ts`). Renewals now do the same: the card is charged the
// remainder, that exact amount is CREDITED to the wallet, and the existing
// CAS-guarded renewal transaction debits the FULL renewal from the wallet. So the
// wallet is always the thing that pays the bill and the card is always just a way
// to fund the wallet — one money path, already proven, and a partial failure can
// never half-apply a renewal.
//
// Plain server module (NOT "use server"): imported by the worker, by server
// actions and by server components. `lib/stripe.ts` is not modified by this file.

import type Stripe from "stripe";
import { db } from "./db";
import { stripe, createCheckoutSessionLogged, stripeConfigured, stripePublishableKey, EMBEDDED_REQUEST_OPTS, CUSTOM_CHECKOUT_UI_MODE, type EmbeddedCheckout } from "./stripe";
import { STRIPE_MIN_CENTS } from "./wallet-split";
import { invoiceCreateData } from "./invoices";
import {
  asStripeError,
  classifyChargeError,
  isNotReusableError,
  paymentMethodUnusableReason,
  type OffSessionResult,
  type UnusableCardReason,
} from "./stripe-charge-errors";
// Re-exported so every existing importer of the classifier/result type from this
// module keeps working; the definitions moved to the pure module so tests and the
// TEST-mode verification script can use them without importing Prisma.
export { classifyChargeError, paymentMethodUnusableReason, unusableCardReasonLabel, type OffSessionResult, type UnusableCardReason } from "./stripe-charge-errors";
// NOTE: no pricing imports here on purpose. `vpsTerm`, `vpsTermPriceCents` and
// `extraDiskCentsAt` were still imported after `renewalCharge` moved out to
// ./renewal-charge, leaving this file holding every ingredient of the renewal
// formula and nothing that used them — an invitation to write the second copy that
// lib/renewal-quote.ts documents two incidents about. The one formula lives in
// ./renewal-charge and is re-exported below.

/* ------------------------------------------------------------------ *
 * Small shared helpers
 * ------------------------------------------------------------------ */

function appBase(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

/** Audit actions used to decide whether an unclaimed Stripe card may be adopted. */
export const CARD_SETUP_STARTED = "card.setup_started";
export const CARD_REMOVED = "card.removed";
export const CARD_SET_PRIMARY = "card.set_primary";

/** How long a "I clicked Add card" intent stays good for the adoption backstop. */
const SETUP_INTENT_TTL_DAYS = 7;

export type CardDisplay = {
  brand: string | null;
  last4: string | null;
  expMonth: number | null;
  expYear: number | null;
};

/** "Visa ···· 4242, expires 04/28" — one formatter for UI, email and audit text. */
export function cardDisplayLabel(card: CardDisplay): string | null {
  if (!card.last4) return null;
  const brand = brandLabel(card.brand);
  const expiry =
    card.expMonth && card.expYear
      ? `, expires ${String(card.expMonth).padStart(2, "0")}/${String(card.expYear).slice(-2)}`
      : "";
  return `${brand} ···· ${card.last4}${expiry}`;
}

/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
export function brandLabel(brand: string | null | undefined): string {
  const map: Record<string, string> = {
    visa: "Visa",
    mastercard: "Mastercard",
    amex: "American Express",
    discover: "Discover",
    diners: "Diners Club",
    jcb: "JCB",
    unionpay: "UnionPay",
    cartes_bancaires: "Cartes Bancaires",
    eftpos_au: "Eftpos",
    link: "Link",
  };
  if (!brand) return "Card";
  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * A card is valid THROUGH the last day of its expiry month, so it stops working
 * at the first instant of the following month. Getting this off by a month would
 * either nag customers a month early or warn them after the renewal already failed.
 */
export function cardExpiresAt(expMonth: number, expYear: number): Date {
  return new Date(Date.UTC(expYear, expMonth, 1));
}

/* ------------------------------------------------------------------ *
 * Renewal pricing — ONE formula, two callers
 * ------------------------------------------------------------------ */

/**
 * What a renewal costs. Lives here (rather than being copied a third time)
 * because BOTH the worker sweep and the customer-facing "settle the balance"
 * link have to quote the same number — `renewNow` and the sweep already carry
 * the comment "the two renewal paths must never disagree", and a self-service
 * pay link that quotes a different total than the sweep charges is exactly how
 * that goes wrong.
 *
 * Pure: prices are passed in so the worker can read the admin settings once per
 * sweep instead of once per server.
 */
// `renewalCharge` and its types now live in ./renewal-charge — a pure module with
// no SDK imports, so client components can price a renewal without pulling the
// Stripe SDK and nodemailer into the browser bundle. Re-exported here so every
// existing server-side importer keeps working unchanged.
export { renewalCharge, type RenewalCharge, type PricedServer } from "./renewal-charge";

/* ------------------------------------------------------------------ *
 * Stripe customer + saving a card
 * ------------------------------------------------------------------ */

export type CardUser = {
  id: string;
  email: string;
  name?: string | null;
  stripeCustomerId: string | null;
  stripePaymentMethodId: string | null;
};

/** True when this account can actually be charged off-session right now. */
export function hasChargeableCard(user: {
  stripeCustomerId: string | null;
  stripePaymentMethodId: string | null;
}): boolean {
  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
}

/**
 * Get-or-create the Stripe customer for an account and remember its id.
 *
 * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
 * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
 * person and strand the card on whichever one lost. The idempotency key — derived
 * only from our own user id — is what stops that: Stripe replays the first
 * customer instead of creating a second.
 */
export async function ensureStripeCustomer(user: CardUser): Promise<string> {
  if (user.stripeCustomerId) return user.stripeCustomerId;
  const fresh = await db.user.findUnique({
    where: { id: user.id },
    select: { stripeCustomerId: true },
  });
  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;

  const customer = await stripe().customers.create(
    {
      email: user.email,
      name: user.name || undefined,
      metadata: { nxeonUserId: user.id },
    },
    { idempotencyKey: `nxeon_customer_${user.id}` },
  );
  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
  return customer.id;
}

/**
 * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
 *
 * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
 * integration anywhere in this codebase and no publishable key plumbed to the
 * browser; a redirect to Stripe's own page reuses the exact flow that already
 * takes money for deploys, upgrades and top-ups.
 *
 * `usage: "off_session"` is load-bearing: it records a mandate that covers the
 * unattended renewal charges we make later. Without it many issuers (and every
 * SCA-regulated card) reject the first off-session charge outright, which would
 * turn "saved card" into "card that is declined once a month".
 */
export async function createCardSetupSession(
  user: CardUser,
  returnPath = "/dashboard/billing",
): Promise<EmbeddedCheckout | null> {
  if (!stripeConfigured()) return null;
  const customerId = await ensureStripeCustomer(user);
  const base = appBase();
  const session = await createCheckoutSessionLogged({
    mode: "setup",
    // Custom Checkout (`ui_mode: "elements"`), the same mode every payment
    // session on the platform was migrated to (see the block comment above
    // CUSTOM_CHECKOUT_UI_MODE in lib/stripe.ts) — mounted client-side via
    // CardSetupModal's `<PaymentElement>`, styled with the shared
    // STRIPE_APPEARANCE/STRIPE_FONTS rather than Stripe's default light
    // theme. This used to be `EMBEDDED_UI_MODE` ("embedded_page", Stripe's
    // own prebuilt page) — the one Stripe surface on the whole platform that
    // never got migrated when everything else did, which is exactly why
    // "Add a card" looked like an unstyled Stripe form. On completion Stripe
    // navigates to `return_url` (returnPath?card_setup=<id>) where the
    // existing finalize-on-return logic runs UNCHANGED — this is a pure
    // presentation change, same Checkout Session shape either way.
    ui_mode: CUSTOM_CHECKOUT_UI_MODE,
    customer: customerId,
    payment_method_types: ["card"],
    setup_intent_data: { metadata: { nxeonUserId: user.id } },
    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
    // returnPath may already carry a query (e.g. the Deploy hub's ?product=hosting),
    // so append card_setup with the correct separator.
    return_url: `${base}${returnPath}${returnPath.includes("?") ? "&" : "?"}card_setup={CHECKOUT_SESSION_ID}`,
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
}

/**
 * Copy the PRIMARY PaymentCard row's fields onto `User`'s mirror columns — the
 * one place that keeps the two in sync. Every renewal/dunning/off-session
 * charge path reads ONLY the `User` columns (`stripePaymentMethodId`,
 * `cardBrand`, etc.), never the `PaymentCard` table directly, so those paths
 * are completely unaffected by a customer having two cards or six: whichever
 * one is primary is always what they see. No primary left (the list is
 * empty) clears the mirror, the same as `clearCardColumns` always did.
 */
async function mirrorPrimaryCardToUser(userId: string, customerId?: string) {
  // `unusableAt: null` is load-bearing: a card Stripe has refused to ever charge
  // again must never be mirrored back onto `User.stripePaymentMethodId`, or the
  // very next sweep would try it (and fail, and loop) all over again.
  const primary = await db.paymentCard.findFirst({ where: { userId, isPrimary: true, unusableAt: null } });
  if (!primary) {
    await clearCardColumns(userId);
    return;
  }
  await db.user.update({
    where: { id: userId },
    data: {
      ...(customerId ? { stripeCustomerId: customerId } : {}),
      stripePaymentMethodId: primary.stripePaymentMethodId,
      cardBrand: primary.brand,
      cardLast4: primary.last4,
      cardExpMonth: primary.expMonth,
      cardExpYear: primary.expYear,
      cardExpiryNotifiedAt: null,
    },
  });
}

/**
 * Add or refresh one card in the customer's list, then re-mirror the primary
 * onto `User`. A card that already exists (same Stripe payment method id —
 * e.g. Checkout re-attaching the same card after a browser refresh) is
 * updated in place, never duplicated. A BRAND NEW card becomes primary only
 * when the customer has no primary yet — adding a second card must never
 * silently switch what a pending renewal is about to charge.
 */
async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod): Promise<boolean> {
  // REUSABILITY GATE (2026-10-01). Only a PaymentMethod ATTACHED to this
  // account's Stripe Customer can ever be charged off-session. A method that
  // arrives unattached — a Checkout session that carried `customer` but no
  // `setup_future_usage` (the old outstanding-balance "settle" link), a guest
  // PaymentIntent, or a card the customer had detached — must NOT be recorded
  // as "the card on file": Stripe refuses every later charge with "may not be
  // used again", and the renewal sweep used to treat that as a transient error
  // and retry it hourly, silently, until suspension. Try to attach first (works
  // for a never-used method); if Stripe refuses, record nothing and leave an
  // audit row so the gap is visible instead of a silent "card saved" that wasn't.
  const reusable = await ensurePaymentMethodAttached(pm, customerId);
  if (!reusable.ok) {
    console.error(`[cards] refusing to record unusable payment method ${pm.id} for user ${userId}: ${reusable.reason} — ${reusable.message}`);
    await db.auditLog
      .create({
        data: {
          userId,
          action: "card.not_reusable",
          detail: `${cardDisplayLabel({
            brand: pm.card?.brand ?? null,
            last4: pm.card?.last4 ?? null,
            expMonth: pm.card?.exp_month ?? null,
            expYear: pm.card?.exp_year ?? null,
          })} not recorded — ${reusable.reason}: ${reusable.message.slice(0, 160)}`,
        },
      })
      .catch(() => {});
    // If this dead method was ALREADY on file (a row written before the gate
    // existed), retire it now rather than wait for a renewal to trip over it.
    const existingRow = await db.paymentCard.findUnique({ where: { stripePaymentMethodId: pm.id } });
    if (existingRow && !existingRow.unusableAt) await markPaymentMethodUnusable(userId, pm.id, reusable.reason);
    return false;
  }
  const existing = await db.paymentCard.findUnique({ where: { stripePaymentMethodId: pm.id } });
  const hasPrimary =
    existing?.isPrimary || (await db.paymentCard.count({ where: { userId, isPrimary: true, unusableAt: null } })) > 0;
  await db.paymentCard.upsert({
    where: { stripePaymentMethodId: pm.id },
    create: {
      userId,
      stripePaymentMethodId: pm.id,
      brand: pm.card?.brand ?? null,
      last4: pm.card?.last4 ?? null,
      expMonth: pm.card?.exp_month ?? null,
      expYear: pm.card?.exp_year ?? null,
      isPrimary: !hasPrimary,
    },
    update: {
      brand: pm.card?.brand ?? null,
      last4: pm.card?.last4 ?? null,
      expMonth: pm.card?.exp_month ?? null,
      expYear: pm.card?.exp_year ?? null,
      // A method that is attached and chargeable again (re-added) is usable again.
      unusableAt: null,
      unusableReason: null,
    },
  });
  await mirrorPrimaryCardToUser(userId, customerId);
  return true;
}

/**
 * Make sure `pm` is attached to `customerId` — attaching it if Stripe still
 * allows that (a fresh method, never consumed), or reporting WHY it never can be.
 * Pure-ish wrapper around `paymentMethodUnusableReason` + one `attach` call.
 */
async function ensurePaymentMethodAttached(
  pm: Stripe.PaymentMethod,
  customerId: string,
): Promise<{ ok: true } | { ok: false; reason: UnusableCardReason; message: string }> {
  const reason = paymentMethodUnusableReason(pm, customerId);
  if (!reason) return { ok: true };
  if (reason === "wrong_customer") {
    return { ok: false, reason, message: `attached to ${typeof pm.customer === "string" ? pm.customer : pm.customer?.id} not ${customerId}` };
  }
  try {
    await stripe().paymentMethods.attach(pm.id, { customer: customerId });
    return { ok: true };
  } catch (e) {
    const err = asStripeError(e);
    if (err?.code === "resource_missing") return { ok: false, reason: "missing_at_stripe", message: String(err.message ?? "") };
    if (isNotReusableError(e) || err) return { ok: false, reason: "not_reusable", message: String(err?.message ?? e) };
    // Network/our-side failure: do not brand the card dead on a wobble — refuse
    // to record it this time (the adoption sweep / next payment can retry).
    return { ok: false, reason: "not_reusable", message: `attach failed: ${String((e as Error)?.message ?? e)}` };
  }
}

/**
 * Retire ONE saved card that Stripe will never charge again: keep the row (so
 * the Billing page can say "re-add this card" and the admin card-health page
 * can list it), drop its primary flag, promote the next-oldest USABLE card if
 * there is one, and re-mirror onto `User` — which clears
 * `stripePaymentMethodId` when nothing usable is left, so `hasChargeableCard`
 * turns false and no sweep ever tries this method again. Idempotent.
 */
export async function markPaymentMethodUnusable(
  userId: string,
  stripePaymentMethodId: string,
  reason: UnusableCardReason,
): Promise<void> {
  const row = await db.paymentCard.findUnique({ where: { stripePaymentMethodId } });
  if (row && row.userId === userId) {
    await db.paymentCard.update({
      where: { id: row.id },
      data: { isPrimary: false, unusableAt: row.unusableAt ?? new Date(), unusableReason: reason },
    });
    if (row.isPrimary) {
      const next = await db.paymentCard.findFirst({
        where: { userId, unusableAt: null },
        orderBy: { createdAt: "asc" },
      });
      if (next) await db.paymentCard.update({ where: { id: next.id }, data: { isPrimary: true } });
    }
  }
  // Whether or not a PaymentCard row existed (legacy mirror-only cards), the
  // User mirror must stop pointing at the dead method.
  const user = await db.user.findUnique({ where: { id: userId }, select: { stripePaymentMethodId: true } });
  if (user?.stripePaymentMethodId === stripePaymentMethodId) {
    await mirrorPrimaryCardToUser(userId);
  }
  await db.auditLog
    .create({
      data: {
        userId,
        action: "card.unusable",
        detail: `${row ? cardDisplayLabel(row) ?? stripePaymentMethodId : stripePaymentMethodId} retired — ${reason}`,
      },
    })
    .catch(() => {});
}

export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };

export type PaymentCardView = {
  id: string; brand: string | null; last4: string | null;
  expMonth: number | null; expYear: number | null; isPrimary: boolean;
  /** True when Stripe will never charge this card again — the customer must re-add it. */
  unusable: boolean;
  unusableReason: string | null;
};

/** Every card a customer has saved, primary first, usable before retired — for the billing page's list. */
export async function listPaymentCards(userId: string): Promise<PaymentCardView[]> {
  const rows = await db.paymentCard.findMany({
    where: { userId },
    orderBy: [{ isPrimary: "desc" }, { unusableAt: { sort: "asc", nulls: "first" } }, { createdAt: "asc" }],
  });
  return rows.map((r) => ({
    id: r.id, brand: r.brand, last4: r.last4, expMonth: r.expMonth, expYear: r.expYear, isPrimary: r.isPrimary,
    unusable: !!r.unusableAt, unusableReason: r.unusableReason,
  }));
}

