import { useCallback, useEffect, useState } from "react";
import {
  CheckoutElementsProvider,
  useCheckoutElements,
  PaymentElement,
} from "@stripe/react-stripe-js/checkout";
import { stripeFor, currentStripeAppearance, useStripeThemeKey, STRIPE_FONTS } from "@/components/customer/PaymentStep";
import { Icon } from "./Icon";

/* The wizard's card sheet.
 *
 * WHY THIS EXISTS RATHER THAN <StripeCheckoutModal/>. There are two different
 * Stripe Checkout Session types in this codebase and they are NOT
 * interchangeable:
 *
 *   ui_mode "embedded_page"  -> createOrderCheckout / lib/stripe-cards.ts
 *                               rendered by <EmbeddedCheckout/> (StripeCheckoutModal)
 *   ui_mode "elements"       -> createOrderPaymentSession (lib/stripe.ts)
 *                               rendered by CheckoutElementsProvider + <PaymentElement/>
 *
 * `payAndDeploy` and its siblings return the SECOND kind. The wizard was handing
 * that client secret to <StripeCheckoutModal/>, which mounts <EmbeddedCheckout/>.
 * The mismatch does not throw: Stripe simply renders NOTHING, so the modal opened
 * with an empty white box, no iframe and no console error, while a perfectly
 * valid $12.99 session sat open in the Stripe dashboard. This component mounts
 * the renderer that matches what the action actually creates.
 *
 * Appearance, fonts and the cached Stripe.js instance are IMPORTED from
 * PaymentStep rather than re-declared, so the wizard's card fields are the same
 * fields the rest of the platform shows — not a second look that drifts.
 * (That file's comment on `STRIPE_FONTS` records why `fontFamily: "inherit"`
 * silently produced Times New Roman: Elements live in a cross-origin iframe.)
 */
export function NxCardFields({
  clientSecret, publishableKey, onConfirmReady, onBusy,
}: {
  clientSecret: string;
  publishableKey: string;
  /* Hands the confirm function UP so the wizard's single primary button can
     drive it. The panel used to carry its own "Pay now" beneath the fields,
     which meant two buttons on one screen — "Pay now" here and "Complete
     deployment" in the summary — with nothing to say which one charged the
     card. The design has one primary action; this keeps it that way while the
     confirm stays where it must live, inside the Elements provider. */
  onConfirmReady: (confirm: (() => Promise<void>) | null) => void;
  onBusy: (busy: boolean, error: string | null) => void;
}) {
  /* Rendered INLINE in the wizard's payment panel, not in an overlay.
   *
   * It began life as a modal and that was wrong twice over: the design puts the
   * card fields in the panel itself, and an overlay inside the wizard's deck is
   * a trap — the deck slides with `transform: translateX()`, which makes it the
   * containing block for `position: fixed`, so a "fixed inset-0" sheet is pinned
   * to the SLIDE rather than the viewport. Measured at top 289 / height 713 in
   * an 1100px viewport, which left the pay button below the fold and
   * unreachable. Inline has no such failure mode.
   *
   * The fields themselves are Stripe's Payment Element, in a cross-origin
   * iframe. That is not a detail to design around: a raw <input> for a card
   * number would put this application in PCI scope. The design's mock inputs
   * show the LAYOUT; Stripe owns the actual fields. */
  const themeKey = useStripeThemeKey();
  return (
    <CheckoutElementsProvider
      /* The client secret is in the key (2026-09-28): Stripe's provider reads
         `clientSecret` ONCE, at init, and ignores a later change. When the
         wizard re-prepared a session because the total moved (a coupon or
         creator code applied), the fields stayed bound to the FIRST session and
         the customer paid its amount — staging: "Pay S$6.53" charged $6.49
         USD-equivalent of the pre-coupon total. A new secret must mount a new
         provider. */
      key={`${themeKey}:${clientSecret}`}
      stripe={stripeFor(publishableKey)}
      options={{
        clientSecret,
        elementsOptions: {
          appearance: currentStripeAppearance(),
          fonts: STRIPE_FONTS,
          /* Saved cards are offered by CardForm's own chooser ("Visa •••• 4242"
             / "Use a different card"), not inside the Payment Element — so
             "Use a different card" opens a genuinely blank card form rather
             than Stripe's saved-card list again. */
          savedPaymentMethod: { enableRedisplay: "never" },
        },
      }}>
      <CardForm onConfirmReady={onConfirmReady} onBusy={onBusy} />
    </CheckoutElementsProvider>
  );
}

/* Stripe brand ids are lowercase slugs ("visa", "amex"). Same labels as
   lib/stripe-cards.ts's `brandLabel`, which is server-only (it imports the db
   client) and so cannot be imported into this client component. */
const BRAND_LABEL: Record<string, string> = {
  visa: "Visa", mastercard: "Mastercard", amex: "American Express", discover: "Discover",
  diners: "Diners Club", jcb: "JCB", unionpay: "UnionPay", cartes_bancaires: "Cartes Bancaires",
  eftpos_au: "Eftpos", link: "Link",
};
function brandName(brand: string | null | undefined): string {
  if (!brand) return "Card";
  return BRAND_LABEL[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

/** "Use a different card" — the value of the chooser's new-card option. */
const NEW_CARD = "new";

/** Only valid inside <CheckoutElementsProvider>. */
function CardForm({ onConfirmReady, onBusy }: {
  onConfirmReady: (confirm: (() => Promise<void>) | null) => void;
  onBusy: (busy: boolean, error: string | null) => void;
}) {
  /* A discriminated union: "loading" while Stripe.js initialises, "error" if it
     failed, "success" once the fields can be confirmed. Every confirm is guarded
     on the inner object existing, so a click during the loading window cannot
     throw — the same discipline as PaymentStep. */
  const state = useCheckoutElements();
  const checkout = state.type === "success" ? state.checkout : undefined;
  const [error, setError] = useState<string | null>(null);

  /* Cards already on file, as the Checkout Session itself reports them — the
     session is created against the customer's Stripe customer
     (ensureStripeCustomer), so these are exactly the cards Stripe will accept
     for it. The provider is mounted with `savedPaymentMethod.enableRedisplay:
     "never"` (see NxCardFields) so the Payment Element below never lists them
     itself: THIS chooser is the one place a saved card is picked, and choosing
     "Use a different card" really does show a blank card form.
     The saved card is pre-selected (it is what the customer already chose to
     keep); switching is one click and switching back is too. */
  const saved = checkout?.savedPaymentMethods ?? [];
  const [choice, setChoice] = useState<string | null>(null);
  const selected = choice && (choice === NEW_CARD || saved.some((c) => c.id === choice))
    ? choice
    : (saved[0]?.id ?? NEW_CARD);
  const useNewCard = selected === NEW_CARD;

  const pay = useCallback(async () => {
    if (!checkout) return;
    setError(null);
    onBusy(true, null);
    try {
      /* A saved card confirms by id; a new card confirms whatever the Payment
         Element holds. Either way it is the SAME session and the SAME
         return_url (/api/stripe/confirm) and fulfilment — which also records
         the card that paid (saveCardFromPaymentSession: PaymentCard mirror +
         the "card.saved (via payment)" audit row), exactly as for a first-time
         card. Nothing card-related is written from here. */
      const res = await checkout.confirm(useNewCard ? {} : { paymentMethod: selected });
      if (res.type === "error") {
        const msg = res.error.message ?? "Your card was declined. Please try another payment method.";
        setError(msg);
        onBusy(false, msg);
        return;
      }
      /* On success Stripe navigates to the session's return_url
         (/api/stripe/confirm) — the SAME route that fulfils every other Stripe
         payment here. There is deliberately nothing to do on this path. */
    } catch {
      const msg = "Something went wrong confirming your payment. Please try again.";
      setError(msg);
      onBusy(false, msg);
      return;
    }
    /* Success does NOT clear busy: Stripe is navigating the browser to the
       session's return_url, and re-enabling the button in that window invites a
       second confirm on a payment that already succeeded. */
  }, [checkout, onBusy, useNewCard, selected]);

  /* Publish the confirm only once the Elements SDK is ready, and withdraw it on
     unmount so the button can never call into a dead provider. */
  useEffect(() => {
    onConfirmReady(checkout ? pay : null);
    return () => onConfirmReady(null);
  }, [checkout, pay, onConfirmReady]);

  if (state.type === "error") {
    return (
      <p className="rounded-[10px] border border-[rgba(239,66,108,0.3)] bg-[rgba(60,10,26,0.5)] px-3 py-2.5 text-[12px] text-rose">
        The card form could not be loaded. Please close this and try again.
      </p>
    );
  }

  const option = (on: boolean) =>
    "flex w-full items-center gap-3 rounded-[10px] border p-3 text-left transition-colors " +
    (on ? "border-[rgba(72,148,255,0.55)] bg-[rgba(26,85,207,0.14)]" : "border-rim bg-surface hover:border-rim-hi");
  const dot = (on: boolean) => (
    <span aria-hidden className={"grid h-[16px] w-[16px] flex-none place-items-center rounded-full border " +
                                 (on ? "border-[#4c8dff]" : "border-rim-hi")}>
      {on && <span className="h-[8px] w-[8px] rounded-full bg-[#4c8dff]" />}
    </span>
  );

  return (
    <div className="flex w-full flex-col gap-4">
      {/* The design's framed enclosure — the visual encapsulation is what does
          the reassurance work, not a badge. */}
      <div className="rounded-[14px] border border-[rgba(72,148,255,0.28)] bg-well p-4
                      shadow-[inset_0_1px_0_rgba(150,200,255,0.06)]">

