// The renewal-method gate, as ONE pure function (no imports, no DB) so the order
// path (`placeHostingOrder`), the wizard quote (lib/nx/quote-hosting.ts), the
// PayPal/local-method quote (lib/actions-payment-providers.ts) and the tests all
// ask the same question the same way.
//
// THE RULE: never open a recurring product the platform has no way to bill again.
// An order qualifies when the account either
//   - has a saved, chargeable card (`hasChargeableCard`: stripeCustomerId AND
//     stripePaymentMethodId — the exact columns the renewal sweeps charge), or
//   - will STILL hold one full renewal in its wallet AFTER today's charge.
//
// "After today's charge" (2026-10-07) — the old inline check compared the balance
// BEFORE the debit, so a $8 wallet buying a $5 plan that renews at $5 passed the
// gate and was left with $3 for a $5 renewal. For a $0 first month the two
// readings are identical.
//
// HISTORY: the first-month-free hosting order used to be EXEMPT from this gate
// (owner decision, 2026-08) so a free month never asked for a card. That left real
// accounts with no card and a $0 wallet whose first renewal could only fail. The
// owner reversed it on 2026-10-07: a free month now captures a card WITHOUT
// charging it (Stripe Checkout `mode: "setup"`), see createHostingOrderSetupSession.

export type RenewalGateInput = {
  /** `hasChargeableCard(user)` — a saved card the sweep can charge off-session. */
  hasCard: boolean;
  /** The wallet balance before this order, in cents. */
  balanceCents: number;
  /** What this order takes from the wallet today, in cents (0 for a free month). */
  dueTodayCents: number;
  /** One full renewal of what is being bought, in cents. */
  renewalCents: number;
};

/** True when the order must capture a renewal card before it can be placed. */
export function renewalMethodMissing(i: RenewalGateInput): boolean {
  if (i.hasCard) return false;
  const after = Math.max(0, i.balanceCents) - Math.max(0, i.dueTodayCents);
  return after < Math.max(0, i.renewalCents);
}
