add='''/**
 * Advisory pre-flight for the renewal-card setup path: the checks
 * `orderHostingAccountFor` would refuse on that a customer can actually fix
 * (domain shape, a taken domain or subdomain, no capacity), run BEFORE we ask for a
 * card — so nobody saves a card for an order that was always going to bounce.
 * Not authoritative: placement re-runs every check inside its own transaction.
 */
async function hostingOrderPreflight(user: User, input: HostingOrderInput): Promise<string | null> {
  const domain = String(input.domain ?? "").trim();
  if (domain) {
    const name = normalizeHostingDomain(domain);
    if (!name || !isValidHostingDomain(name)) return "Enter a valid domain (e.g. example.com).";
    const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
    if (dupe) {
      return dupe.userId === user.id
        ? "You already have a hosting account for this domain."
        : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.";
    }
    if (await isHostnameClaimed(name)) return "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.";
  } else {
    const label = String(input.subdomainLabel ?? "").trim().toLowerCase();
    if (label) {
      if (!isValidSubdomainLabel(label)) return "Choose a subdomain of 1–32 letters, digits or hyphens (start/end with a letter or digit).";
      const fqdn = freeSubdomainFor(label);
      if (!isValidHostingDomain(fqdn)) return "That subdomain isn’t a valid hostname — try a different one.";
      if (await isHostnameClaimed(fqdn)) return `${fqdn} is already taken — please choose another subdomain.`;
    }
  }
  if (!(await scheduleHostingNode())) return "No shared-hosting capacity is available right now — please try again shortly.";
  return null;
}

/**
 * Open the "save a renewal card — nothing is charged today" Stripe session for a
 * hosting order that needs one (2026-10-07). The deploy wizard calls this when its
 * quote says `renewalCardRequired` and nothing is owed on a card today.
 *
 * NEVER PLACES AN ORDER and never touches the wallet — so, unlike `placeHostingOrder`,
 * it is safe to call merely because the payment step is on screen. It re-runs the
 * same pricing + gate as `placeHostingOrder` against the signed-in account and
 * returns `{ notRequired }` when no card is needed (a card already on file, a
 * wallet that covers the renewal, or a card leg due today, which saves the card on
 * its own). Otherwise it returns a `mode: "setup"` session (lib/stripe.ts
 * createHostingOrderSetupSession) carrying this exact order; fulfilment saves the
 * card and then places the order, debiting at most the `dueCents` stamped here.
 */
export async function prepareHostingRenewalCard(
  input: HostingOrderInput,
): Promise<
  | { setup: EmbeddedCheckout; dueTodayCents: number; renewalCents: number; renewsAt: string }
  | { notRequired: true }
  | { error: string }
> {
  const user = await requireUser();
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const key = String(input.idempotencyKey ?? "").trim();
  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t prepare the order — please reload and try again." };

  const term = normalizeProductTerm(input.termMonths);
  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
  const renewalCents = await hostingRenewalCents(plan, term, extraGB);

  // The SAME eligibility + due-today + split placeHostingOrder computes.
  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
  const { dueCents: dueTodayCents } = await hostingOrderDueCents(plan, term, extraGB, {
    userId: user.id,
    firstMonthFreeEligible: eligible,
  });
  const { cardCents } = walletSplit({ dueCents: dueTodayCents, balanceCents: user.balanceCents, useWallet: input.useWallet !== false });
  if (cardCents > 0) return { notRequired: true };
  if (!renewalMethodMissing({ hasCard: hasChargeableCard(user), balanceCents: user.balanceCents, dueTodayCents, renewalCents })) {
    return { notRequired: true };
  }
  if (!stripeConfigured()) return { error: "Card payments aren’t set up yet — this plan renews automatically and needs a card." };

  const problem = await hostingOrderPreflight(user, input);
  if (problem) return { error: problem };

  const intent: HostOrderSetupIntent = {
    planId: plan.id,
    domain: String(input.domain ?? "").trim() || undefined,
    subdomainLabel: String(input.subdomainLabel ?? "").trim() || undefined,
    extraDiskGB: extraGB || undefined,
    termMonths: term,
    appSlug: input.appSlug || undefined,
    idempotencyKey: key,
    partnerSource: partnerSourceFromCookie(await cookies()),
    dueCents: dueTodayCents,
    ipHash,
  };
  try {
    const setup = await createHostingOrderSetupSession(user, intent);
    if (!setup) return { error: "Stripe didn’t return a card form. Please try again." };
    // Evidence for the adoption backstop (adoptUnclaimedCards) that this customer
    // really did start saving a card — same row the billing page's flow writes.
    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED, detail: "hosting renewal card" } }).catch(() => {});
    return { setup, dueTodayCents, renewalCents, renewsAt: addMonths(new Date(), term).toISOString() };
  } catch (e) {
    console.error("[hosting] renewal-card setup session failed", e);
    return { error: "We couldn’t open the card form just now. Please try again in a moment." };
  }
}

/**
 * Fulfilment for a completed hosting renewal-card SETUP session (lib/fulfil-checkout.ts
 * `hostOrderSetup`). The caller has ALREADY saved the card as the account's renewal
 * method; this re-reads the session from Stripe (the id may come from a URL, so it is
 * never trusted on its own), re-checks that the account now has a chargeable card,
 * and places the order through the same `placeHostingOrderCore` (same
 * `hostorder:<key>` idempotency) — with the debit capped at the stamped `dueCents`
 * and eligibility decided by the customer's own stamped ipHash.
 */
export async function placeHostingSetupOrder(
  sessionId: string,
): Promise<HostingOrderResult | { skip: true }> {
  const purpose = await getCheckoutPurpose(sessionId);
  if (purpose.kind !== "hostOrderSetup") return { skip: true };
  const user = await db.user.findUnique({ where: { id: purpose.userId } });
  if (!user) return { error: "user not found for hosting setup order" };
  if (!hasChargeableCard(user)) return { error: "The renewal card wasn’t saved, so the order was not placed. Nothing was charged." };
  const intent = purpose.intent;
  const term = normalizeProductTerm(intent.termMonths);
  const plan = await db.hostingPlan.findUnique({ where: { id: intent.planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
  const extraGB = normalizeExtraDiskAddGB(intent.extraDiskGB);
  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
  const input: HostingOrderInput = {
    planId: intent.planId,
    domain: intent.domain,
    subdomainLabel: intent.subdomainLabel,
    extraDiskGB: intent.extraDiskGB,
    termMonths: intent.termMonths,
    appSlug: intent.appSlug,
    idempotencyKey: intent.idempotencyKey,
    useWallet: true,
  };
  return placeHostingOrderCore(user, input, intent.idempotencyKey, term, plan, extraGB, renewalCents, intent.partnerSource, {
    ipHash: intent.ipHash,
    maxDebitCents: intent.dueCents,
  });
}

