/* ------------------------------------------------------------------ *
 * Shared-hosting order — mirrors placeHostingOrder's first-month-free path
 * (lib/actions-hosting.ts), no coupon/VAT.
 * ------------------------------------------------------------------ */

export type HostingExternalInput = {
  planId: string;
  domain?: string;
  subdomainLabel?: string;
  extraDiskGB?: number;
  termMonths?: number;
  appSlug?: string;
  idempotencyKey: string;
  useWallet?: boolean;
};

async function quoteHostingOrderForExternalPayment(
  input: HostingExternalInput,
): Promise<{ error: string } | { cardCents: number; metadata: Record<string, string> }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  const key = String(input.idempotencyKey ?? "").trim();
  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn't start the order — please reload and try again." };

  const partnerSource = partnerSourceFromCookie(await cookies());
  const term = normalizeProductTerm(input.termMonths);
  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn't available." };
  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);

  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
  // Creator Partner Program discount included — the same hostingOrderDueCents
  // placeHostingOrder splits on and orderHostingAccountFor debits.
  const { dueCents: dueTodayCents } = await hostingOrderDueCents(plan, term, extraGB, {
    userId: user.id,
    firstMonthFreeEligible: eligible,
  });
  const useWallet = input.useWallet !== false;
  const { cardCents } = walletSplit({ dueCents: dueTodayCents, balanceCents: user.balanceCents, useWallet });
  if (cardCents <= 0) {
    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
  }

  const intent = {
    planId: input.planId,
    domain: input.domain,
    subdomainLabel: input.subdomainLabel,
    extraDiskGB: extraGB || undefined,
    termMonths: term,
    appSlug: input.appSlug,
    idempotencyKey: key,
    partnerSource,
  };
  const metadata: Record<string, string> = {
    nxeonUserId: user.id,
    nxeonHostOrder: packExternalPaymentMetadata("Hosting order intent", intent),
  };
  return { cardCents, metadata };
}

export async function createHostingOrderPayPalOrder(input: HostingExternalInput): Promise<CreatePayPalOrderResult> {
  const user = await requireUser();
  const quoted = await quoteHostingOrderForExternalPayment(input);
  if ("error" in quoted) return quoted;
  return openPayPal({ userId: user.id, kind: "hostOrder", amountCents: quoted.cardCents, metadata: quoted.metadata, description: "Nxeon shared hosting order" });
}

export async function createHostingOrderCoinbaseCharge(input: HostingExternalInput): Promise<CreateCoinbaseChargeResult> {
  const user = await requireUser();
  const quoted = await quoteHostingOrderForExternalPayment(input);
  if ("error" in quoted) return quoted;
  return openCoinbase({
    userId: user.id,
    kind: "hostOrder",
    amountCents: quoted.cardCents,
    metadata: quoted.metadata,
    name: "Nxeon Shared Hosting",
    description: "Nxeon shared hosting order",
    redirectPath: "/dashboard/deploy?product=hosting&paid=1",
    cancelPath: "/dashboard/deploy?product=hosting",
  });
}

