anchor='''  /* The wizard's real <form>. PayPal reads its FormData from THIS element, so
     it can only ever order exactly what the card path would. */
  const formRef = useRef<HTMLFormElement>(null);'''
assert s.count(anchor)==1
add='''  /* WEB HOSTING RENEWAL CARD (2026-10-07). Hosting renews automatically, so an
     order on an account with no saved card — a free first month ($0 today), or a
     total the balance covers while the balance won't also cover month two — must
     capture a card WITHOUT charging it. The quote says so (`renewalCardRequired`,
     the same gate placeHostingOrder enforces); `prepareHostingRenewalCard` then
     opens a Stripe `mode: "setup"` session for exactly this order. It NEVER places
     the order, so (unlike `action`) it is safe to call because this step is on
     screen. Confirming the card fields saves the card; fulfilment then places the
     order (debiting at most what the summary shows) and lands on the new account.
     Keyed on the whole order: a setup session carries the order it will place, so
     a changed plan/term/name must never confirm the old one. */
  const renewalCardOnly = isHosting && !!price?.renewalCardRequired;
  const needsRenewalSetup = renewalCardOnly && price !== null && cardDue <= 0;
  const setupKey = needsRenewalSetup && ready
    ? JSON.stringify([o.hostingPlanId, o.termMonths, cleanDomainInput(o.domain), o.subdomainLabel.trim(), o.useWallet])
    : null;
  type SetupPrep = { key: string; clientSecret: string; publishableKey: string; renewsAt: string };
  const [setupPrep, setSetupPrep] = useState<SetupPrep | null>(null);
  const [setupErr, setSetupErr] = useState<string | null>(null);
  const [setupNonce, setSetupNonce] = useState(0);
  const setupKeyRef = useRef<string | null>(null);
  setupKeyRef.current = setupKey;
  const setupTried = useRef<string | null>(null);
  const setupCheckout = setupPrep && setupPrep.key === setupKey ? setupPrep : null;
  useEffect(() => {
    if (!active || !methods.card || !setupKey || pricing || !o.hostingPlanId) return;
    const attempt = `${setupKey}:${setupNonce}`;
    if (setupTried.current === attempt) return;
    setupTried.current = attempt;
    setSetupErr(null);
    const key = setupKey;
    const t = setTimeout(async () => {
      try {
        const res = await prepareHostingRenewalCard({
          planId: o.hostingPlanId!,
          domain: cleanDomainInput(o.domain) || undefined,
          subdomainLabel: o.subdomainLabel.trim() || undefined,
          termMonths: o.termMonths,
          idempotencyKey: idemKey,
          useWallet: o.useWallet,
        });
        if (setupKeyRef.current !== key) return; // the order changed; that session simply expires
        if ("setup" in res) {
          setSetupPrep({ key, clientSecret: res.setup.clientSecret, publishableKey: res.setup.publishableKey, renewsAt: res.renewsAt });
        } else if ("error" in res) {
          setSetupPrep(null);
          setSetupErr(res.error);
          if (trackedProduct) trackDeployError(trackedProduct, "Payment", paymentStepIndex, "ORDER_ERROR", res.error);
        } else {
          /* The server no longer needs a card (one was just saved in another tab,
             or the balance moved): fall back to the ordinary submit. */
          setSetupPrep(null);
        }
      } catch (e) {
        if (reportIfStaleClient(e)) return;
        if (setupKeyRef.current === key) setSetupErr("We couldn't open the card form. Please try again.");
      }
    }, 400);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, methods.card, setupKey, setupNonce, pricing]);
  useEffect(() => { if (setupErr) trackErrorShown(setupErr, "deploy payment (hosting renewal card)"); }, [setupErr]);
  /* "$0 today · renews at $X/mo on <date> · cancel anytime" — the renewal figure
     is the quote's renewalTotalCents (what the sweep will charge), the date is the
     server's own expiry for this order once it has answered. */
  const renewDate = (() => {
    if (setupCheckout) return new Date(setupCheckout.renewsAt);
    const d = new Date();
    d.setMonth(d.getMonth() + o.termMonths);
    return d;
  })();
  const renewLine = price
    ? `${money(cardDue > 0 ? cardDue : 0)} today · renews at ${money(price.renewalTotalCents)}${o.termMonths === 1 ? "/mo" : ` every ${o.termMonths} months`} on ${renewDate.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })} · cancel anytime`
    : "";

'''
s=s.replace(anchor, add+anchor)
open(p,'w').write(s)
