/* Three pieces of portal chrome the design had no counterpart for, drawn in the
   Nexion language rather than left in the old one.
 *
 * They share a shape on purpose — one rule, one icon plate, one line of copy,
 * one action — because they interrupt the page and an interruption should be
 * the same size every time. What differs is the accent, and the accent carries
 * the whole meaning: amber asks, magenta warns, and only the impersonation bar
 * is allowed to be loud. */

/* ── the rule every banner sits on ──────────────────────────────────────────
   A hairline in the accent, brightest at the left where the icon is, fading
   out across the width. It is what makes these read as one family without
   giving each of them a heavy border. */
function AccentRule({ rgb }: { rgb: string }) {
  return (
    <span
      aria-hidden
      className="pointer-events-none absolute inset-x-0 top-0 h-px"
      style={{ background: `linear-gradient(90deg, rgba(${rgb},0.85), rgba(${rgb},0.12) 42%, transparent 80%)` }}
    />
  );
}

function Banner({
  rgb, icon, children, action, onDismiss,
}: {
  rgb: string;
  icon: string;
  children: React.ReactNode;
  action?: React.ReactNode;
  onDismiss?: () => void;
}) {
  return (
    <div
      // Themed, not dark-locked: this used to force the always-dark island
      // treatment so its token-driven text (text-white, text-tx-mute,
      // text-tx-body) wouldn't vanish against a hardcoded dark wash — but a
      // permanently dark bar sitting on an otherwise white light-mode page
      // read as a leftover bug, not a design. `.nx-banner-wash` (globals.css)
      // carries a real light-mode background instead, so removing the island
      // lets the text tokens flip color normally, and the accent (--banner-rgb,
      // set below) keeps this reusable for any future banner tone, not just
      // amber.
      //
      // z-[2]: this renders in the dashboard layout BEFORE the page body — on
      // any page mounting one of the fixed, `z-0` animated *Aurora canvases
      // (SSL, domains, migrate, tools...) that puts this banner and the aurora
      // at the same implicit stack level with no explicit z-index, so paint
      // order falls back to DOM tree order and the aurora (later in the tree)
      // draws over this (earlier) banner instead of the reverse — exactly the
      // "purple lines showing through" report on /dashboard/ssl. An explicit
      // z-index moves this into its own higher paint step regardless of tree
      // order, same as the pages that already wrap their own hero in
      // `relative z-[1]` for the identical reason. Kept below the sticky
      // rail/header (z-20/z-30) and the mobile nav/notifications (z-40/z-50).
      className="nx-banner-wash relative z-[2] flex items-center gap-3 overflow-hidden rounded-[12px] border px-3.5 py-2.5"
      style={{
        "--banner-rgb": rgb,
        borderColor: `rgba(${rgb},0.28)`,
      } as CSSProperties}
    >
      <AccentRule rgb={rgb} />
      <span
        className="grid h-[30px] w-[30px] flex-none place-items-center rounded-[8px]"
        style={{
          background: `rgba(${rgb},0.14)`,
          border: `1px solid rgba(${rgb},0.30)`,
          color: `rgb(${rgb})`,
          boxShadow: `inset 0 0 14px -6px rgba(${rgb},0.55)`,
        }}
