// Shared hosting accounts that will reach a renewal with NO way to pay it
// (2026-10-07). Before the deploy wizard asked for a renewal card, a first-month-
// free hosting order opened the account with no saved card and (usually) a $0
// wallet; worker/product-renewals.ts hostingDueSweep can only charge the wallet or
// a saved card, so those first renewals can only fail.
//
// Plain server module (NOT "use server"): read by the portal layout (the in-app
// banner, gated off by default) and by scripts/hosting-card-gap-report.ts. It only
// READS — it never emails, notifies or changes anything.

import { db } from "./db";
import { annualDiscountPct } from "./annual-discount";
import { extraDiskPerGbCents } from "./disk-expand";
import { hostingRenewalPrice } from "./product-billing";

/** States the renewal sweep will bill (ACTIVE) or soon will (PENDING/PROVISIONING). */
const BILLABLE = ["PENDING", "PROVISIONING", "ACTIVE"] as const;

export type HostingCardGap = {
  accountId: string;
  userId: string;
  primaryDomain: string;
  planName: string;
  expiresAt: Date;
  renewalCents: number;
  balanceCents: number;
  /** Staff/owner/test account (role not CUSTOMER, or excluded from revenue). */
  internal: boolean;
};

/**
 * Card-on-file test from the COLUMNS alone — the exact pair `hasChargeableCard`
 * requires — so the report script gives the same answer without Stripe env vars
 * (hasChargeableCard also requires STRIPE_SECRET_KEY to be set in this process).
 */
function hasCardColumns(u: { stripeCustomerId: string | null; stripePaymentMethodId: string | null }): boolean {
  return !!u.stripeCustomerId && !!u.stripePaymentMethodId;
}

/**
 * Every billable hosting account whose owner has no saved card and whose wallet
 * won't cover that account's next renewal (pre-partner-discount price, the
 * conservative figure). Optionally scoped to one user (the banner).
 */
export async function findHostingCardGaps(opts: { userId?: string } = {}): Promise<HostingCardGap[]> {
  const rows = await db.hostingAccount.findMany({
    where: {
      status: { in: [...BILLABLE] },
      expiresAt: { not: null },
      ...(opts.userId ? { userId: opts.userId } : {}),
      user: { OR: [{ stripeCustomerId: null }, { stripePaymentMethodId: null }] },
    },
    include: {
      plan: { select: { name: true, priceCents: true } },
      user: {
        select: { id: true, balanceCents: true, stripeCustomerId: true, stripePaymentMethodId: true, role: true, excludeFromRevenue: true },
      },
    },
    orderBy: { expiresAt: "asc" },
  });
  if (!rows.length) return [];
  const liveAnnual = await annualDiscountPct();
  const perGb = await extraDiskPerGbCents();
  const out: HostingCardGap[] = [];
  for (const a of rows) {
    if (!a.expiresAt || hasCardColumns(a.user)) continue;
    const renewalCents = hostingRenewalPrice(a, liveAnnual, perGb);
    if (a.user.balanceCents >= renewalCents) continue;
    out.push({
      accountId: a.id,
      userId: a.userId,
      primaryDomain: a.primaryDomain,
      planName: a.plan.name,
      expiresAt: a.expiresAt,
      renewalCents,
      balanceCents: a.user.balanceCents,
      internal: a.user.role !== "CUSTOMER" || a.user.excludeFromRevenue,
    });
  }
  return out;
}
