/**
 * READ-ONLY report: shared hosting accounts heading into a renewal with no saved
 * card and a wallet that won't cover it (2026-10-07). These are the accounts the
 * first-month-free exemption left without a renewal method; worker/product-
 * renewals.ts can only charge the wallet or a saved card, so their renewal fails.
 *
 * Prints COUNTS and DATES only — no email addresses, names or domains — plus the
 * account id so the owner can look one up in admin. It never emails, notifies or
 * writes: the session is forced READ ONLY at the database (one pooled connection,
 * `default_transaction_read_only`), so even a bug here could not change a row.
 *
 *   DATABASE_URL=... npx tsx scripts/hosting-card-gap-report.ts [--include-internal]
 *
 * The drafted email (lib/mailer.ts emails.hostingRenewalCardNeeded) and the in-app
 * banner (setting hosting_card_banner_enabled, default off) are NOT triggered by
 * this script — sending anything is the owner's call.
 */
async function main() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");
  // One connection, so the READ ONLY session setting below covers every query.
  const u = new URL(url);
  u.searchParams.set("connection_limit", "1");
  process.env.DATABASE_URL = u.toString();

  const { db } = await import("../lib/db");
  await db.$executeRawUnsafe("SET SESSION CHARACTERISTICS AS TRANSACTION READ ONLY");
  const ro = await db.$queryRawUnsafe<{ transaction_read_only: string }[]>("SHOW transaction_read_only");
  if (ro[0]?.transaction_read_only !== "on") throw new Error("could not make the session read-only; refusing to continue");

  const { findHostingCardGaps } = await import("../lib/hosting-card-gap");
  const includeInternal = process.argv.includes("--include-internal");
  const all = await findHostingCardGaps();
  const rows = includeInternal ? all : all.filter((g) => !g.internal);
  const now = Date.now();
  const day = (d: Date) => d.toISOString().slice(0, 10);

  console.log(`Hosting accounts with no renewal method: ${rows.length} (${all.length - all.filter((g) => !g.internal).length} internal/staff ${includeInternal ? "included" : "excluded"})`);
  console.log(`Distinct customers: ${new Set(rows.map((r) => r.userId)).size}`);
  const overdue = rows.filter((r) => r.expiresAt.getTime() <= now).length;
  console.log(`Already past renewal date: ${overdue}`);
  console.log("");
  console.log("renews_on   | plan               | renewal | wallet  | account_id");
  for (const r of rows) {
    console.log(
      `${day(r.expiresAt)}  | ${r.planName.padEnd(18).slice(0, 18)} | $${(r.renewalCents / 100).toFixed(2).padStart(6)} | $${(r.balanceCents / 100).toFixed(2).padStart(6)} | ${r.accountId}${r.internal ? "  (internal)" : ""}`,
    );
  }
  await db.$disconnect();
}

main().catch((e) => {
  console.error(e instanceof Error ? e.message : e);
  process.exit(1);
});
EOF
