import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { renewalMethodMissing } from "../lib/renewal-method-gate.ts";
import { classifyCheckoutSession } from "../lib/stripe.ts";

/**
 * The renewal-method gate and the hosting renewal-card SETUP session's
 * classification (2026-10-07). Pure — no database, no Stripe.
 *
 * Owner request: "make sure we are asking for credit cards for the shared hosting
 * so renewals actually work". A free first month used to skip this gate, so real
 * accounts were opened with no card and a $0 wallet.
 */

test("a free first month with no card and an empty wallet NEEDS a renewal card", () => {
  assert.equal(renewalMethodMissing({ hasCard: false, balanceCents: 0, dueTodayCents: 0, renewalCents: 299 }), true);
});

test("a saved card always satisfies the gate, whatever the wallet holds", () => {
  assert.equal(renewalMethodMissing({ hasCard: true, balanceCents: 0, dueTodayCents: 0, renewalCents: 299 }), false);
  assert.equal(renewalMethodMissing({ hasCard: true, balanceCents: 0, dueTodayCents: 899, renewalCents: 899 }), false);
});

test("a wallet that still holds one renewal AFTER today's debit satisfies the gate", () => {
  assert.equal(renewalMethodMissing({ hasCard: false, balanceCents: 299, dueTodayCents: 0, renewalCents: 299 }), false);
  assert.equal(renewalMethodMissing({ hasCard: false, balanceCents: 1000, dueTodayCents: 500, renewalCents: 500 }), false);
});

test("the wallet is judged AFTER today's charge, not before it", () => {
  // $8 wallet, $5 due today, $5 renewal: the old pre-debit check passed this and
  // left $3 for a $5 renewal.
  assert.equal(renewalMethodMissing({ hasCard: false, balanceCents: 800, dueTodayCents: 500, renewalCents: 500 }), true);
});

test("negative inputs never make the gate pass by accident", () => {
  assert.equal(renewalMethodMissing({ hasCard: false, balanceCents: -100, dueTodayCents: 0, renewalCents: 299 }), true);
});

/* ------------------------------------------------------------------ *
 * Classification of the setup session
 * ------------------------------------------------------------------ */

const intent = { planId: "plan_1", idempotencyKey: "abcdefgh1234", dueCents: 0, ipHash: "iphash", termMonths: 1, subdomainLabel: "mysite" };

function setupSession(over: Record<string, unknown> = {}) {
  return {
    mode: "setup",
    status: "complete",
    payment_status: "no_payment_required",
    metadata: { nxeonUserId: "user_1", nxeonHostOrderSetup: JSON.stringify(intent) },
    ...over,
  } as never;
}

test("a COMPLETE setup session carrying a hosting order classifies as hostOrderSetup with the stamped intent", () => {
  const p = classifyCheckoutSession(setupSession());
  assert.equal(p.kind, "hostOrderSetup");
  if (p.kind !== "hostOrderSetup") return;
  assert.equal(p.userId, "user_1");
  assert.equal(p.intent.planId, "plan_1");
  assert.equal(p.intent.dueCents, 0);
  assert.equal(p.intent.ipHash, "iphash");
  assert.equal(p.intent.subdomainLabel, "mysite");
});

test("an OPEN (not yet confirmed) setup session is unpaid — nothing is placed", () => {
  assert.equal(classifyCheckoutSession(setupSession({ status: "open" })).kind, "unpaid");
});

test("the setup key on a PAYMENT-mode session is refused as unreadable, never guessed at", () => {
  assert.equal(classifyCheckoutSession(setupSession({ mode: "payment", payment_status: "paid" })).kind, "unreadable");
});

test("a setup intent without its stamped dueCents is unreadable — fulfilment must know the agreed figure", () => {
  const { dueCents: _drop, ...rest } = intent;
  const p = classifyCheckoutSession(setupSession({ metadata: { nxeonUserId: "user_1", nxeonHostOrderSetup: JSON.stringify(rest) } }));
  assert.equal(p.kind, "unreadable");
});

test("a card-paid hosting order keeps its partnerSource through classification", () => {
  const p = classifyCheckoutSession({
    payment_status: "paid",
    metadata: { nxeonUserId: "u", nxeonHostOrder: JSON.stringify({ planId: "p", idempotencyKey: "abcdefgh1234", partnerSource: "kodely" }) },
  } as never);
  assert.equal(p.kind, "hostOrder");
  if (p.kind === "hostOrder") assert.equal(p.intent.partnerSource, "kodely");
});

/* ------------------------------------------------------------------ *
 * Source guards — the exemption must not quietly come back
 * ------------------------------------------------------------------ */

test("placeHostingOrder no longer exempts the free first month from the gate", () => {
  const src = readFileSync(new URL("../lib/actions-hosting.ts", import.meta.url), "utf8");
  assert.ok(!/const freeFirstMonth = eligible && dueTodayCents === 0/.test(src), "the free-month exemption is back");
  assert.ok(/renewalMethodMissing\(\{ hasCard: hasChargeableCard\(user\)/.test(src), "placeHostingOrder must call the shared gate");
});

test("the hosting PayPal/Coinbase/local quote enforces the same gate", () => {
  const src = readFileSync(new URL("../lib/actions-payment-providers.ts", import.meta.url), "utf8");
  const fn = src.slice(src.indexOf("async function quoteHostingOrderForExternalPayment"), src.indexOf("export async function createHostingOrderPayPalOrder"));
  assert.ok(/renewalMethodMissing\(/.test(fn), "hosting external-payment quote must gate on a renewal method");
});

