import { test, before, after, mock } from "node:test";
import assert from "node:assert/strict";

/**
 * DB-backed proof of the hosting renewal-card flow (2026-10-07), end to end through
 * the REAL order, fulfilment and renewal code against a THROWAWAY Postgres, with a
 * FAKE Stripe client (no network): the Stripe singleton's resource methods are
 * replaced so every call is recorded and nothing leaves this process.
 *
 *   1. A first-month-free order on an account with no card and a $0 wallet is
 *      REFUSED by placeHostingOrder (`needCard`) — nothing placed.
 *   2. prepareHostingRenewalCard opens a `mode: "setup"` session (no amount, no
 *      line items) carrying the order and the agreed $0 — still nothing placed.
 *   3. Fulfilling that completed setup session SAVES the card as the account's
 *      renewal method, THEN places the order: $0 debited, no PaymentIntent created.
 *      Replaying it (webhook + redirect) places nothing more.
 *   4. The renewal sweep then charges that saved card off-session for the renewal.
 *   5. A setup session whose agreed $0 no longer holds (the free month was already
 *      used) debits NOTHING, even with money in the wallet.
 *
 * Opt-in and fail-closed, like test/local-order-fulfilment.test.ts: runs only when
 * HOSTCARD_TEST_DATABASE_URL is set, equals DATABASE_URL, and points at 127.0.0.1 on
 * a non-default port with a database named `hostcard`. Run with
 *   tsx --test --experimental-test-module-mocks test/hosting-renewal-card-db.test.ts
 */
