const st = new Stripe(process.env.STRIPE_SECRET_KEY);
(async () => {
  const u = await db.user.findUniqueOrThrow({ where: { id: userId } });
  console.log("user card:", { cus: u.stripeCustomerId, pm: u.stripePaymentMethodId, last4: u.cardLast4, balanceCents: u.balanceCents });
  const accts = await db.hostingAccount.findMany({ where: { userId } });
  console.log("hosting accounts:", accts.map((a) => ({ id: a.id, status: a.status, expiresAt: a.expiresAt, domain: a.primaryDomain })));
  const tx = await db.walletTransaction.findMany({ where: { userId }, orderBy: { createdAt: "asc" } });
  console.log("wallet tx:", tx.map((t) => [t.amountCents, t.description]));
  const fs = await db.fulfilledSession.findMany({ where: { OR: [{ kind: "hostOrderSetup" }, { kind: "hostorder" }] }, orderBy: { createdAt: "desc" }, take: 3 });
  console.log("fulfilled:", fs.map((f) => [f.stripeSessionId.slice(0, 24), f.kind, f.status]));
  if (!u.stripeCustomerId) return;
  const pis = await st.paymentIntents.list({ customer: u.stripeCustomerId, limit: 10 });
  console.log("Stripe PaymentIntents BEFORE renewal:", pis.data.length);
  const sis = await st.setupIntents.list({ customer: u.stripeCustomerId, limit: 5 });
  console.log("Stripe SetupIntents:", sis.data.map((s) => ({ id: s.id, status: s.status, usage: s.usage, pm: s.payment_method })));
  const pm = u.stripePaymentMethodId ? await st.paymentMethods.retrieve(u.stripePaymentMethodId) : null;
  console.log("PM attached to customer:", pm?.customer === u.stripeCustomerId, pm?.card?.brand, pm?.card?.last4);
  if (process.argv.includes("--renew") && accts[0]) {
    await db.hostingAccount.update({ where: { id: accts[0].id }, data: { status: "ACTIVE", expiresAt: new Date(Date.now() - 60_000) } });
