cd /tank/nxeon-wt-hostcard && cat >> test/hosting-renewal-card-db.test.ts <<'EOF'

test("a setup fulfilment left CLAIMED by a crashed process is retaken once stale; a fresh claim is not", { skip }, async () => {
  const { prepareHostingRenewalCard } = await import("../lib/actions-hosting.ts");
  const { fulfilRetrievedCheckoutSession } = await import("../lib/fulfil-checkout.ts");
  const user = await newCustomer("d");
  const input = { planId, subdomainLabel: `hcd${Date.now() % 1e8}`, termMonths: 1, idempotencyKey: `hostcardtestd${Date.now()}`, useWallet: true };
  assert.ok("setup" in (await prepareHostingRenewalCard(input)));
  const session = completedSetupSession(`pm_d_${RUN}`);
  const s = (await import("../lib/stripe.ts")).stripe() as unknown as { checkout: { sessions: Record<string, unknown> } };
  s.checkout.sessions.retrieve = async () => session;
  // A live claim (someone else is fulfilling right now): left alone.
  await db.fulfilledSession.create({ data: { stripeSessionId: session.id, kind: "hostOrderSetup" } });
  const busy = await fulfilRetrievedCheckoutSession(session as never, "https://example.test");
  assert.equal(busy.fulfilled, false);
  assert.equal(await db.hostingAccount.count({ where: { userId: user.id } }), 0);
  // The process died: the claim goes stale and the next delivery finishes the job.
  await db.$executeRawUnsafe(`UPDATE "FulfilledSession" SET "updatedAt" = now() - interval '10 minutes' WHERE "stripeSessionId" = $1`, session.id);
  const res = await fulfilRetrievedCheckoutSession(session as never, "https://example.test");
  assert.equal(res.fulfilled, true, res.error);
  assert.equal(await db.hostingAccount.count({ where: { userId: user.id } }), 1);
  // And a later replay lands on the account rather than the list.
  const again = await fulfilRetrievedCheckoutSession(session as never, "https://example.test");
  assert.match(again.redirect, /\/dashboard\/hosting\/[^/?]+\?purchase=1$/);
  assert.equal(await db.hostingAccount.count({ where: { userId: user.id } }), 1);
});
EOF
