  // The process died: the claim goes stale and the next delivery finishes the job.
  await db.$executeRawUnsafe(`UPDATE "FulfilledSession" SET "updatedAt" = now() - interval '10 minutes' WHERE "stripeSessionId" = $1`, session.id);
